head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[gridView > M > getFocusedColumnID]<br/>포커스된 Cell 의 Column ID 값을 반환합니다.",
    "validation" : [
        "포커스된 Cell 의 Column ID 값을 반환하여야 합니다.",
        "포커스된 Cell 이 없는 경우 null 값을 반환하여야 합니다.",
        "Ctrl, Shift 키를 이용하여 여러 Cell 을 포커스 한 경우 마지막에 포커스 된 Cell 을 기준으로 동작하여야 합니다.",
    ]
}



scwin.onpageload = function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // comp 초기 생성
    scwin.comp_init();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



// comp 생성
scwin.comp_init = async function () {
    // 기존 target 있으면 삭제
    if (typeof dlt_bind !== 'undefined') {
        $p.data.remove("dlt_bind");
    }

    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    // 조건 설정
    let properties = {
        useShiftKey: "true",
        dataList: "data:dlt_bind",
    };

    let cList = $c.gcm.createCList(properties);

    // dataList 생성
    $c.gcm.createBasicDataList('', '', 'dlt_bind');

    // target 생성
    $c.gcm.createBasicGridView(cList);
}



scwin.btn_getFocusedColumnID_onclick = function () {
    let rtn = target1.getFocusedColumnID();
    wf_body_bottom.getObj("scwin").setReturnValue("getFocusedColumnID : " + rtn);
}
